@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&display=swap');
:root{--paper:#f2f0e9;--ink:#171816;--muted:#77776f;--red:#e44d32;--line:#d5d3ca;--green:#d6e363;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:82px}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}button,input{font:inherit}button,a{-webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button{color:inherit}.announcement{height:31px;background:var(--ink);color:var(--paper);display:flex;align-items:center;justify-content:center;gap:14px;font:10px var(--mono);letter-spacing:.055em}.announcement b{color:var(--green);font-weight:500}.announcement-dot{color:var(--red);font-size:13px}.site-header{height:76px;padding:0 6.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:10;background:var(--paper)}.wordmark{font:700 29px/.9 var(--display);letter-spacing:-.09em;position:relative}.wordmark span{color:var(--red)}.wordmark i{font:9px var(--mono);position:absolute;right:-11px;top:-3px;letter-spacing:0}.main-nav{display:flex;gap:40px;margin-left:70px}.main-nav a,.text-link{font:10px var(--mono);letter-spacing:.07em}.main-nav a{transition:color .2s}.main-nav a:hover,.text-link:hover{color:var(--red)}.header-actions{display:flex;align-items:center;gap:21px}.icon-btn{width:30px;height:34px;background:none;border:0;padding:4px;cursor:pointer;position:relative}.icon-btn svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.5}.cart-count{position:absolute;right:-5px;top:0;width:16px;height:16px;border-radius:50%;background:var(--red);color:white;display:grid;place-items:center;font:9px var(--mono)}.menu-toggle{display:none}.search-panel{display:none;position:absolute;z-index:12;top:107px;left:0;right:0;background:var(--paper);padding:24px 12%;border-bottom:1px solid var(--line);box-shadow:0 15px 25px #17181612}.search-panel.open{display:block}.search-panel label,.newsletter-form label{font:10px var(--mono);letter-spacing:.08em}.search-row{display:flex;border-bottom:1px solid var(--ink);margin-top:7px}.search-row input{border:0;background:none;outline:0;flex:1;padding:13px 0;font:20px var(--display)}.search-submit{border:0;background:none;font:10px var(--mono);cursor:pointer}.hero{padding:0 6.1%;min-height:570px;display:grid;grid-template-columns:1fr .95fr;position:relative;overflow:hidden}.hero-copy{padding:75px 0 46px;display:flex;flex-direction:column;align-items:flex-start;z-index:1}.eyebrow{display:flex;align-items:center;gap:9px;font:10px var(--mono);letter-spacing:.065em}.eyebrow-line{width:25px;height:1px;background:var(--red)}h1,h2,h3,p{margin-top:0}.hero h1{font:700 clamp(58px,7.7vw,107px)/.84 var(--display);letter-spacing:-.09em;margin:36px 0 23px}.hero h1 span{color:var(--red)}.hero-copy>p{font-size:15px;line-height:1.55;color:#55554f;margin-bottom:26px}.button{min-height:51px;padding:0 19px;display:inline-flex;align-items:center;justify-content:center;gap:24px;border:1px solid var(--ink);font:10px var(--mono);letter-spacing:.055em;cursor:pointer;transition:background .2s,color .2s,border .2s}.button-dark{background:var(--ink);color:var(--paper)}.button-dark:hover{background:var(--red);border-color:var(--red)}.button span{font-size:16px}.hero-footnote{display:flex;align-items:center;gap:12px;margin-top:auto;font:9px var(--mono);letter-spacing:.06em}.hero-footnote-line{height:1px;width:62px;background:var(--red)}.hero-image{position:relative;overflow:hidden;background:#d3d0c7;min-height:570px}.hero-image>img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover;object-position:center 36%;filter:saturate(.78)}.hero-image:after{content:'';position:absolute;inset:45% 0 0;background:linear-gradient(transparent,#14130f8c)}.hero-sticker{width:104px;height:104px;border-radius:50%;background:var(--green);position:absolute;z-index:2;right:8%;top:9%;display:flex;flex-direction:column;justify-content:center;align-items:center;transform:rotate(12deg);font:9px var(--mono);line-height:1.1;text-align:center}.hero-sticker b{font:700 30px/.95 var(--display);letter-spacing:-.09em}.hero-image-caption{position:absolute;z-index:2;bottom:25px;left:25px;right:25px;display:flex;justify-content:space-between;color:#fff;font:9px/1.35 var(--mono);letter-spacing:.08em}.hero-index{position:absolute;right:2.5%;bottom:32px;writing-mode:vertical-rl;font:9px var(--mono);letter-spacing:.1em;color:var(--muted)}.ticker{height:52px;background:var(--red);overflow:hidden;display:flex;align-items:center;color:var(--paper)}.ticker-track{white-space:nowrap;display:flex;align-items:center;justify-content:space-around;min-width:100%;gap:35px;font:700 15px var(--display);letter-spacing:.02em;animation:marquee 26s linear infinite}.ticker-track b{font-size:18px;color:var(--green)}@keyframes marquee{to{transform:translateX(-22%)}}.section-wrap{padding:92px 6.1% 98px}.section-heading{display:flex;justify-content:space-between;align-items:flex-end}.section-heading h2,.manifesto h2,.newsletter h2{font:700 clamp(40px,5vw,63px)/.92 var(--display);letter-spacing:-.075em;margin:20px 0 0}.section-heading h2 span,.manifesto h2 span,.newsletter h2 span{color:var(--red)}.text-link{display:inline-flex;align-items:center;gap:14px;padding-bottom:5px;border-bottom:1px solid var(--ink)}.text-link span{font-size:14px}.collection-toolbar{display:flex;align-items:center;justify-content:space-between;margin:39px 0 20px;border-bottom:1px solid var(--line);padding-bottom:15px}.filter-list{display:flex;gap:9px}.filter-chip{border:1px solid var(--line);background:transparent;padding:10px 13px;font:9px var(--mono);letter-spacing:.045em;cursor:pointer;transition:.2s}.filter-chip span{margin-left:7px;color:var(--red)}.filter-chip.active,.filter-chip:hover{background:var(--ink);border-color:var(--ink);color:var(--paper)}.results-count{font:9px var(--mono);color:var(--