er-radius:50%;border:1px solid #7775}.swatch.black{background:#242522}.swatch.cream{background:#e8e4d8}.swatch.red{background:#bd4a3a}.swatch.green{background:#737656}.swatch.blue{background:#344a65}.empty-products{text-align:center;padding:70px;font:12px var(--mono)}.clear-search{display:block;margin:16px auto 0;background:none;border:0;border-bottom:1px solid;font:10px var(--mono);padding:7px;cursor:pointer}.mobile-collection-link{display:none}.manifesto{min-height:530px;background:#1a1b18;color:var(--paper);display:grid;grid-template-columns:1.05fr .95fr}.manifesto-image{position:relative;min-height:530px;overflow:hidden}.manifesto-image img{width:100%;height:100%;position:absolute;object-fit:cover;filter:saturate(.55) brightness(.78)}.image-label{position:absolute;bottom:20px;left:6.1%;font:9px var(--mono);letter-spacing:.1em}.manifesto-copy{position:relative;padding:80px 10% 70px 12%;overflow:hidden}.manifesto h2{font-size:clamp(47px,5.6vw,74px);margin:29px 0 24px}.manifesto-copy>p{max-width:345px;color:#b9b8b1;font-size:13px;line-height:1.75;margin-bottom:25px}.manifesto .text-link{border-color:#9c9b95;font-size:9px}.manifesto-mark{position:absolute;right:8%;bottom:-31px;color:#ffffff0a;font:700 180px/.9 var(--display);letter-spacing:-.1em}.manifesto-mark span{font:30px var(--mono);vertical-align:top}.values{display:grid;grid-template-columns:repeat(3,1fr);padding:70px 10.2%;gap:7%;border-bottom:1px solid var(--line)}.values>div{position:relative;padding-left:28px}.value-number{position:absolute;left:0;top:3px;color:var(--red);font:10px var(--mono)}.values h3{font:600 19px/1.05 var(--display);letter-spacing:-.04em;margin:0 0 12px}.values p{font-size:11px;color:var(--muted);line-height:1.6;margin:0;max-width:210px}.newsletter{position:relative;padding:75px 10.2%;display:flex;align-items:center;justify-content:space-between;overflow:hidden}.newsletter h2{font-size:52px;margin:20px 0 14px}.newsletter>div>p{font-size:12px;color:var(--muted);margin:0}.newsletter-form{width:37%;max-width:400px;position:relative;z-index:1}.email-row{display:flex;border-bottom:1px solid var(--ink);margin-top:8px}.email-row input{flex:1;min-width:0;border:0;outline:0;background:none;padding:11px 0;font:14px var(--display)}.email-row button{border:0;background:none;font-size:23px;cursor:pointer}.form-note{font:8px var(--mono);color:var(--muted);display:block;margin-top:10px;letter-spacing:.05em}.newsletter-star{position:absolute;right:3.5%;top:20px;color:#e44d3217;font-size:185px;line-height:1}footer{background:var(--ink);color:var(--paper);padding:35px 6.1% 20px}.footer-top{display:flex;align-items:center;justify-content:space-between;padding-bottom:35px;border-bottom:1px solid #ffffff2b}.footer-logo{font-size:31px}.footer-top p{font:9px/1.6 var(--mono);letter-spacing:.05em;color:#b5b4ac;margin:0}.social-links{display:flex;gap:20px}.social-links a,.footer-bottom{font:9px var(--mono);letter-spacing:.04em}.social-links a:hover,.footer-bottom a:hover{color:var(--green)}.footer-bottom{padding-top:18px;display:flex;justify-content:space-between;color:#a6a69e;font-size:8px}.footer-bottom div{display:flex;gap:22px}.drawer-scrim{position:fixed;inset:0;background:#111b;z-index:30;opacity:0;visibility:hidden;transition:.25s}.cart-drawer{position:fixed;z-index:31;right:0;top:0;height:100dvh;width:min(450px,100%);background:var(--paper);transform:translateX(102%);transition:transform .3s ease;display:flex;flex-direction:column;padding:27px 28px}.cart-open .drawer-scrim{opacity:1;visibility:visible}.cart-open .cart-drawer{transform:translateX(0)}.drawer-header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:19px}.drawer-header .eyebrow{font-size:8px}.drawer-header h2{font:700 29px var(--display);letter-spacing:-.06em;margin:11px 0 0}.drawer-header h2 span{font:12px var(--mono);color:var(--muted);letter-spacing:0}.close-drawer{font-size:30px;background:none;border:0;cursor:pointer;font-weight:300}.cart-items{overflow:auto;flex:1}.cart-line{display:grid;grid-template-columns:78px 1fr auto;gap:14px;padding:17px 0;border-bottom:1px solid var(--line)}.cart-line img{width:78px;height:96px;object-fit:cover;background:#ddd}.cart-line h3{font:600 12px var(--display);margin:2px 0 6px}.cart-line p{font:8px var(--mono);color:var(--muted);margin:0}.cart-line-price{font:11px var(--mono);white-space:nowrap}.cart-line-controls{display:flex;align-items:center;gap:10px;margin-top:14px}.qty-btn{width:23px;height:23px;border:1px solid var(--line);background:none;cursor:pointer}.qty-number{font:10px var(--mono)}.remove-item{margin-left:auto;border:0;background:none;text-decoration:underline;color:var(--muted);font:8px var(--mono);cursor:pointer}.cart-empty{text-align:center;margin:auto}.cart-empty>span{font-size:39px;color:var(--red)}.cart-empty h3{font:700 29px/.95 var(--display);letter-spacing:-.06em;margin:15px 0 9px}.cart-empty p{font-size:12px;color:var(--muted);margin-bottom:20px}.cart-empty .button{width:100%}.cart-footer{border-top:1px solid var(--line);padding-top:17px}.shipping-progress{font:8px var(--mono);letter-spacing:.03em}.progress-track{height:3px;background:var(--line);margin-top:9px}.progress-track i{height:100%;width:0;background:var(--red);display:block;transition:width .2s}.subtotal{display:flex;justify-content:space-between;margin:18px 0;font:10px var(--mono)}.subtotal b{font-weight:500}.checkout-btn{width:100%;justify-content:space-between}.checkout-note{display:block;text-align:center;font:7px var(--mono);color:var(--muted);margin-top:10px}.cart-footer:has(+.x){display:none}.cart-drawer:not(.has-items) .cart-footer{display:none}.cart-drawer.has-items .cart-empty{display:none}.toast{position:fixed;z-index:50;bottom:22px;left:50%;transform:translate(-50%,20px);padding:13px 19px;background:var(--ink);color:white;font:10px var(--mono);opacity:0;visibility:hidden;transition:.25s;white-space:nowrap}.toast.show{opacity:1;visibility:visible;transform:translate(-50%,0)}
