  }

  function handleCheckoutSubmit(event) {
    if (!event.target.closest('.checkout-form')) return;
    event.preventDefault();
    const form = event.target.closest('.checkout-form');
    const error = form.querySelector('.checkout-error');
    error.hidden = true;
    const values = Object.fromEntries(new FormData(form));
    if (!values.name || !values.phone || !values.zip || !values.address || !values.city || !values.state) {
      error.textContent = 'Preencha os dados de entrega para continuar.';
      error.hidden = false;
      return;
    }
    try {
      const order = RUA98.createOrder({
        payment: values.payment,
        customer: values
      });
      checkoutElements.body.innerHTML = `
        <div class="checkout-success">
          <span class="checkout-success-star">✳</span>
          <span class="eyebrow">PEDIDO CONFIRMADO</span>
          <h3>AGORA É<br><span>COM A GENTE.</span></h3>
          <p>Pedido <b>#${order.number}</b> registrado com sucesso.<br>Você acompanha tudo em Minha Conta.</p>
          <div class="checkout-success-actions">
            <a class="button button-dark" href="conta.html#pedidos">VER MEUS PEDIDOS <span>↗</span></a>
            <button class="button checkout-success-close" type="button">CONTINUAR COMPRANDO</button>
          </div>
        </div>
      `;
      toast(`PEDIDO #${order.number} CONFIRMADO ✳`);
    } catch (orderError) {
      error.textContent = orderError.message;
      error.hidden = false;
    }
  }

  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape') return;
    if (checkoutElements?.modal.classList.contains('open')) closeCheckout();
    if (authElements?.modal.classList.contains('open')) closeAuth();
  });

  window.addEventListener('rua98:auth', () => {
    refreshHeader();
    renderAccountMenu();
  });
  window.addEventListener('rua98:data', () => {
    refreshHeader();
    renderAccountMenu();
  });

  const AuthUI = {
    init() {
      injectAuthModal();
      injectAccountButton();
      injectCheckout();
    },
    openAuth,
    closeAuth,
    openCheckout,
    closeCheckout,
    refreshHeader,
    toast,
    requireLogin(message = 'Entre para continuar.') {
      if (RUA98.currentUser()) return true;
      pendingAction = null;
      openAuth('login', message);
      return false;
    }
  };

  window.AuthUI = AuthUI;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => AuthUI.init());
  else AuthUI.init();
})();

/* RUA 98 — loja */
(async () => {
  await RUA98.ready();

  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[char]));
  const price = value => `R$ ${Number(value).toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}`;
  const state = { category: 'todos', collection: 'todos', search: '' };
  const grid = document.querySelector('#product-grid');
  const filterList = document.querySelector('#filter-list');
  const collectionFilter = document.querySelector('#collection-filter');
  const resultsCount = document.querySelector('.results-count');
  const emptyProducts = document.querySelector('.empty-products');
  const drawer = document.querySelector('.cart-drawer');

  function applySettings() {
    const settings = RUA98.settings();
    const announcementParts = document.querySelectorAll('.announcement > span:not(.announcement-dot)');
    if (announcementParts[0]) announcementParts[0].textContent = settings.announcement;
    if (announcementParts[1]) announcementParts[1].textContent = settings.announcementTwo;
    const shippingLabel = document.querySelector('.shipping-progress > span');
    if (shippingLabel) shippingLabel.textContent = `FRETE GRÁTIS A PARTIR DE ${price(settings.freeShipping)}`;
    const heroEyebrow = document.querySelector('.hero .eyebrow');
    if (heroEyebrow) {
      const drop = RUA98.activeDrop();
      const label = drop ? drop.name : settings.heroEyebrow;
      heroEyebrow.innerHTML = '<span class="eyebrow-line"></span> ';
      heroEyebrow.append(document.createTextNode(label));
    }
    const instagram = document.querySelector('.social-links a[aria-label="Instagram"]');
    if (instagram && settings.instagram) instagram.href = settings.instagram;
    const whatsapp = document.querySelector('.social-links a[aria-label="TikTok"]');
    if (whatsapp && settings.whatsapp) whatsapp.href = settings.whatsapp;
    const checkoutNote = document.querySelector('.checkout-note');
    if (checkoutNote) checkoutNote.textContent = settings.checkoutNote;
  }

  function activeProducts() {
    return RUA98.products().filter(product => product.active);
  }

  function renderFilters() {
    const products = activeProducts();
    const count = category => category === 'todos' ? products.length : products.filter(product => product.category === category).length;
    filterList.innerHTML = [
      { id: 'todos', label: 'TUDO' },
      { id: 'oversized', label: 'OVERSIZED' },
      { id: 'old-school', label: 'OLD SCHOOL' }
    ].map(item => `
      <button class="filter-chip${state.category === item.id ? ' active' : ''}" data-filter="${item.id}">
        ${item.label} <span>${String(count(item.id)).padStart(2, '0')}</span>
      </button>`).join('');
    const collections = RUA98.collections();
    collectionFilter.innerHTML = '<option value="todos">TODAS</option>' + collections
      .map(collection => `<option value="${esc(collection.id)}">${esc(collection.name.toUpperCase())}</option>`)
      .join('');
    collectionFilter.value = state.collection;
  }

  function filteredProducts() {
    const collections = new Map(RUA98.collections({ includeInactive: true }).map(collection => [collection.id, collection.name]));
    const term = state.search.trim().toLowerCase();
    return activeProducts().filter(product => {
      const matchesCategory = state.category === 'todos' || product.category === state.category;
      const matchesCollection = state.collection === 'todos' || product.collectionId === state.collection;
      const haystack = [product.name, product.subtitle, product.tag, product.description, collections.get(product.collectionId) || '']
        .join(' ').toLowerCase();
      return matchesCategory && matchesCollection && (!term || haystack.includes(term));
    });
  }

  function productCard(product) {
    const favorite = RUA98.isFavorite(product.id);
    const collection = RUA98.collection(product.collectionId);
    const tagClass = product.isNew ? 'tag-new' : /LIMITADA|ESGOTADO/.test(product.tag) ? 'tag-limited' : '';
    const soldOut = product.stock <= 0;
    return `
      <article class="product-card" data-category="${esc(product.category)}" data-collection="${esc(product.collectionId)}" data-id="${esc(product.id)}" data-name="${esc(product.name.toLowerCase())}">
        <div class="product-image">
          <img src="${esc(product.image)}" alt="${esc(product.name)}" loading="lazy">
          ${product.tag ? `<span class="product-tag ${tagClass}">${esc(soldOut ? 'ESGOTADO' : product.tag)}</span>` : soldOut ? '<span class="product-tag tag-limited">ESGOTADO</span>' : ''}
          <button class="favorite-btn${favorite ? ' active' : ''}" data-favorite="${esc(product.id)}" aria-label="${favorite ? 'Remover dos favoritos' : 'Favoritar'} ${esc(product.name)}" aria-pressed="${favorite}">
            <svg viewBox="0 0 24 24"><path d="M20.8 8.7c0 5.2-8.8 10-8.8 10s-8.8-4.8-8.8-10a4.7 4.7 0 0 1 8.8-2.2 4.7 4.7 0 0 1 8.8 2.2Z"/></svg>
          </button>
          <button class="quick-add" data-product="${esc(product.id)}" ${soldOut ? 'disabled' : ''}>
            ${soldOut ? 'ESGOTADO' : 'ADICIONAR À SACOLA'} <span>${soldOut ? '×' : '＋'}</span>
          </button>
        </div>
        <div class="product-info">
          <div><h3>${esc(product.name)}</h3><span class="product-subtitle">${esc(product.subtitle || product.meta)}</span></div>
          <span class="product-price">${price(product.price)}${product.compareAt ? `<s>${price(product.compareAt)}</s>` : ''}</span>
        </div>
        <div class="product-meta">
          <span>${esc(product.meta || '100% ALGODÃO')}</span>
          <span class="collection-name">${esc(collection ? collection.name : 'RUA 98')}</span>
        </div>
      </article>`;
  }

  function renderProducts() {
    const products = filteredProducts();
    grid.innerHTML = products.map(productCard).join('');
    resultsCount.textContent = `MOSTRANDO ${String(products.length).padStart(2, '0')} ${products.length === 1 ? 'PEÇA' : 'PEÇAS'}`;
    emptyProducts.hidden = products.length > 0;
    grid.hidden = products.length === 0;
    renderFilters();
  }

  function renderCart() {
    const cart = RUA98.cart();
    const settings = RUA98.settings();
    const total = cart.subtotal;
    document.querySelector('.cart-count').textContent = cart.count;
    document.querySelector('.drawer-item-count').textContent = `(${cart.count})`;
    document.querySelector('.subtotal b').textContent = price(total);
    const shippingLabel = document.querySelector('.shipping-progress > span');
    shippingLabel.textContent = total >= settings.freeShipping
      ? 'VOCÊ GANHOU FRETE GRÁTIS!'
      : `FALTAM ${price(settings.freeShipping - total)} PARA O FRETE GRÁTIS`;
    document.querySelector('.progress-track i').style.width = `${Math.min(100, (total / settings.freeShipping) * 100)}%`;
    drawer.classList.toggle('has-items', cart.count > 0);
    document.querySelector('.cart-items').innerHTML = cart.lines.map(line => `
      <article class="cart-line">
        <img src="${esc(line.product.image)}" alt="${esc(line.product.name)}">
        <div>
          <h3>${esc(line.product.name)}</h3>
          <p>${esc(line.product.subtitle)}<br>TAMANHO: ${esc(line.size)}</p>
          <div class="cart-line-controls">
            <button class="qty-btn" data-action="minus" data-product="${esc(line.productId)}" data-size="${esc(line.size)}" aria-label="Diminuir quantidade">−</button>
            <span class="qty-number">${line.quantity}</span>
            <button class="qty-btn" data-action="plus" data-product="${esc(line.productId)}" data-size="${esc(line.size)}" aria-label="Aumentar quantidade">+</button>
            <button class="remove-item" data-action="remove" data-product="${esc(line.productId)}" data-size="${esc(line.size)}">REMOVER</button>
          </div>
        </div>
        <span class="cart-line-price">${price(line.total)}</span>
      </article>`).join('');
    const checkoutButton = document.querySelector('.checkout-btn');
    checkoutButton.disabled = cart.count === 0;
  }

  function openCart() {
    document.body.classList.add('cart-open');
    drawer.setAttribute('aria-hidden', 'false');
    document.querySelector('.close-drawer').focus();
  }
  function closeCart() {
    document.body.classList.remove('cart-open');
    drawer.setAttribute('aria-hidden', 'true');
  }

  function openSizePicker(button) {
    const image = button.closest('.product-image');
    const product = RUA98.product(button.dataset.product);
    if (!product) return;
    document.querySelectorAll('.size-picker').forEach(picker => picker.remove());
    if (product.stock <= 0) {
      AuthUI.toast('ESSA PEÇA ESGOTOU. VOLTA LOGO ✳');
      return;
    }
    const picker = document.createElement('div');
    picker.className = 'size-picker';
    picker.setAttribute('aria-label', 'Escolha o tamanho');
    picker.innerHTML = `<span>ESCOLHA SEU TAMANHO · ${product.stock} EM ESTOQUE</span><div>${product.sizes.map(size => `<button type="button" data-size="${esc(size)}">${esc(size)}</button>`).join('')}</div>`;
    image.append(picker);
    picker.querySelectorAll('button').forEach(sizeButton => sizeButton.addEventListener('click', event => {
      event.stopPropagation();
      try {
        RUA98.addToCart(product.id, sizeButton.dataset.size);
        picker.remove();
        renderCart();
        AuthUI.toast(`${product.name} · TAM. ${sizeButton.dataset.size} NA SACOLA ✳`);
        openCart();
      } catch (error) {
        AuthUI.toast(error.message.toUpperCase());
        picker.remove();
      }
    }));
  }

  filterList.addEventListener('click', event => {
    const button = event.target.closest('[data-filter]');
    if (!button) return;
    state.category = button.dataset.filter;
    renderProducts();
  });

  collectionFilter.addEventListener('change', event => {
    state.collection = event.target.value;
    renderProducts();
  });

  grid.addEventListener('click', event => {
    const favoriteButton = event.target.closest('[data-favorite]');
    if (favoriteButton) {
      try {
        const result = RUA98.toggleFavorite(favoriteButton.dataset.favorite);
        AuthUI.toast(result.active ? 'PEÇA SALVA NOS SEUS FAVORITOS ✳' : 'PEÇA REMOVIDA DOS FAVORITOS');
        renderProducts();
        AuthUI.refreshHeader();
      } catch (error) {
        AuthUI.toast(error.message.toUpperCase());
      }
      return;
    }
    const addButton = event.target.closest('.quick-add');
    if (addButton && !addButton.disabled) openSizePicker(addButton);
  });

  document.querySelector('.cart-toggle').addEventListener('click', openCart);
  document.querySelector('.close-drawer').addEventListener('click', closeCart);
  document.querySelector('.drawer-scrim').addEventListener('click', closeCart);
  document.querySelector('.continue-shopping').addEventListener('click', () => {
    closeCart();
    document.querySelector('#colecao').scrollIntoView({ behavior: 'smooth' });
  });
  document.querySelector('.checkout-btn').addEventListener('click', () => AuthUI.openCheckout());

  document.querySelector('.cart-items').addEventListener('click', event => {
    const button = event.target.closest('[data-action]');
    if (!button) return;
    const { action, product, size } = button.dataset;
    if (action === 'plus') RUA98.updateCartQuantity(product, size, 1);
    if (action === 'minus') RUA98.updateCartQuantity(product, size, -1);
    if (action === 'remove') RUA98.removeCartItem(product, size);
    renderCart();
  });

  document.querySelector('.search-toggle').addEventListener('click', () => {
    const panel = document.querySelector('.search-panel');
    panel.classList.toggle('open');
    if (panel.classList.contains('open')) document.querySelector('#search-input').focus();
  });
  document.querySelector('#search-input').addEventListener('input', event => {
    state.search = event.target.value;
    renderProducts();
  });
  document.querySelector('.search-submit').addEventListener('click', () => {
    document.querySelector('.search-panel').classList.remove('open');
    document.querySelector('#colecao').scrollIntoView({ behavior: 'smooth' });
  });
  document.querySelector('.clear-search').addEventListener('click', () => {
    state.search = '';
    state.category = 'todos';
    state.collection = 'todos';
    document.querySelector('#search-input').value = '';
    document.querySelector('#collection-filter').value = 'todos';
    renderProducts();
  });

  document.querySelector('.menu-toggle').addEventListener('click', event => {
    const nav = document.querySelector('.main-nav');
    const open = nav.classList.toggle('open');
    event.currentTarget.setAttribute('aria-expanded', String(open));
  });
  document.querySelectorAll('.main-nav a').forEach(link => link.addEventListener('click', () => {
    document.querySelector('.main-nav').classList.remove('open');
    document.querySelector('.menu-toggle').setAttribute('aria-expanded', 'false');
  }));

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      closeCart();
      document.querySelector('.search-panel').classList.remove('open');
      document.querySelector('.main-nav').classList.remove('open');
      document.querySelectorAll('.size-picker').forEach(picker => picker.remove());
    }
  });

  document.querySelector('.newsletter-form').addEventListener('submit', event => {
    event.preventDefault();
    const email = document.querySelector('#email');
    if (!email.checkValidity()) return email.reportValidity();
    AuthUI.toast('VOCÊ TÁ NA LISTA! CONFERE SEU E-MAIL ✳');
    event.currentTarget.reset();
  });

  window.addEventListener('rua98:auth', () => {
    renderProducts();
    renderCart();
  });
  window.addEventListener('rua98:data', () => {
    renderFilters();
    renderProducts();
    renderCart();
  });

  applySettings();
  renderProducts();
  renderCart();
  AuthUI.refreshHeader();
})();

/* RUA 98 — autenticação, conta do cliente e checkout */
body.auth-open,
body.checkout-open { overflow: hidden; }

/* ---------- menu da conta no header ---------- */
.account-wrap { position: relative; }
.account-btn {
  display: flex; align-items: center; gap: 9px; background: none; border: 0;
  padding: 4px 0; cursor: pointer;
}
.account-avatar {
  width: 29px; height: 29px; border-radius: 50%; border: 1px solid var(--ink);
  display: grid; place-items: center; font: 500 10px var(--mono); overflow: hidden;
  transition: background .2s, color .2s;
}
.account-avatar svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.account-avatar.filled { background: var(--ink); color: var(--paper); }
.account-btn:hover .account-avatar { background: var(--red); border-color: var(--red); color: white; }
.account-label { font: 9px var(--mono); letter-spacing: .06em; max-width: 80px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.account-menu {
  position: absolute; right: -6px; top: calc(100% + 17px); width: 286px; background: var(--ink);
  color: var(--paper); z-index: 40; padding: 20px; box-shadow: 0 20px 50px #17181638;
}
.account-menu[hidden] { display: none; }
.account-hello { display: flex; flex-direction: column; gap: 5px; padding-bottom: 16px; border-bottom: 1px solid #ffffff26; }
.account-hello .eyebrow { font-size: 7px; color: var(--green); }
.account-hello b { font: 600 18px var(--display); letter-spacing: -.03em; }
.account-email { font: 8px var(--mono); color: #a9a8a0; overflow: hidden; text-overflow: ellipsis; }
.account-menu a, .account-logout {
  display: flex; align-items: center; justify-content: space-between; width: 100%;
  background: none; border: 0; border-bottom: 1px solid #ffffff1c; color: var(--paper);
  padding: 13px 0; font: 9px var(--mono); letter-spacing: .045em; text-align: left; cursor: pointer;
}
.account-menu a:hover, .account-logout:hover { color: var(--green); }
.account-menu a span { font-size: 13px; }
.account-menu .account-admin { color: var(--green); }
.account-logout { color: #ed8a79; border-bottom: 0; padding-bottom: 2px; }

/* ---------- modal de login ---------- */
.auth-scrim, .checkout-scrim {
  position: fixed; inset: 0; background: #10110f9e; z-index: 60; opacity: 0; visibility: hidden;
  transition: opacity .25s, visibility .25s; backdrop-filter: blur(3px);
}
.auth-scrim.open, .checkout-scrim.open { opacity: 1; visibility: visible; }
.auth-modal {
  position: fixed; z-index: 61; top: 50%; left: 50%; transform: translate(-50%, -46%);
  width: min(430px, calc(100% - 32px)); max-height: calc(100dvh - 40px); overflow: auto;
  background: var(--paper); padding: 38px 38px 24px; opacity: 0; visibility: hidden;
  transition: opacity .25s, transform .25s, visibility .25s; box-shadow: 0 30px 80px #00000038;
}
.auth-modal.open { opacity: 1; visibility: visible; transform: translate(-50%, -50%); }
.auth-close, .checkout-close {
  position: absolute; right: 15px; top: 9px; background: none; border: 0;
  font: 300 31px var(--display); cursor: pointer; line-height: 1; padding: 4px;
}
.auth-brand { font: 700 22px/.9 var(--display); letter-spacing: -.09em; margin-bottom: 24px; }
.auth-brand span { color: var(--red); }
.auth-brand i { font: 7px var(--mono); vertical-align: super; margin-left: 2px; }
.auth-eyebrow { font-size: 8px; }
.auth-title { font: 700 43px/.9 var(--display); letter-spacing: -.075em; margin: 14px 0 19px; }
.auth-title span { color: var(--red); }
.auth-message {
  background: var(--green); padding: 10px 12px; font: 8.5px/1.5 var(--mono);
  margin: 0 0 18px; letter-spacing: .02em;
}
.auth-message[hidden] { display: none; }
.auth-tabs { display: flex; border-bottom: 1px solid var(--line); margin-bottom: 20px; }
.auth-tabs button {
  flex: 1; padding: 11px 4px; background: none; border: 0; border-bottom: 2px solid transparent;
  font: 9px var(--mono); letter-spacing: .06em; cursor: pointer; color: var(--muted);
}
.auth-tabs button.active { border-color: var(--ink); color: var(--ink); }
.auth-form { display: flex; flex-direction: column; }
.auth-form[hidden] { display: none; }
.auth-form label {
  display: flex; flex-direction: column; gap: 6px; margin-bottom: 14px;
  font: 8px var(--mono); letter-spacing: .06em;
}
.auth-form input {
  border: 1px solid var(--line); background: #fffdf8; padding: 12px 11px;
  font: 14px var(--display); outline: 0; border-radius: 0; color: var(--ink);
}
.auth-form input:focus { border-color: var(--ink); }
.auth-form input::placeholder { color: #a3a29a; }
.auth-error {
  background: #f7d9d2; color: #952f1e; padding: 9px 11px; margin: 0 0 13px;
  font: 8.5px/1.5 var(--mono);
}
.auth-error[hidden] { display: none; }
.auth-submit { width: 100%; justify-content: space-between; margin-top: 2px; }
.auth-submit:disabled { opacity: .65; cursor: wait; }
.auth-demo {
  border: 0; background: none; text-decoration: underline; font: 8px var(--mono);
  letter-spacing: .05em; color: var(--muted); padding: 12px 0 0; cursor: pointer;
}
.auth-demo:hover { color: var(--red); }
.auth-note { font: 8px/1.7 var(--mono); color: var(--muted); margin: 12px 0 0; letter-spacing: .015em; }
.auth-note b { font-weight: 500; color: var(--ink); }
.auth-trust {
  margin: 22px -38px -24px; padding: 11px 12px; background: #e7e4da; color: #817f75;
  display: flex; align-items: center; justify-content: center; gap: 9px;
  font: 6.5px var(--mono); letter-spacing: .05em;
}
.auth-trust span { color: var(--red); font-size: 9px; }

/* ---------- filtro de coleção ---------- */
.toolbar-right { display: flex; align-items: center; gap: 23px; }
.collection-select-wrap { display: flex; align-items: center; gap: 8px; font: 8px var(--mono); color: var(--muted); }
.collection-select-wrap select {
  border: 0; border-bottom: 1px solid var(--ink); background: transparent; border-radius: 0;
  padding: 5px 18px 5px 0; font: 8px var(--mono); color: var(--ink); outline: 0; cursor: pointer;
}
.product-price s { display: block; color: var(--muted); font-size: 9px; margin-top: 3px; }
.collection-name { max-width: 95px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.quick-add:disabled { background: #53544f; cursor: not-allowed; }

/* ---------- checkout ---------- */
.checkout-modal {
  position: fixed; z-index: 61; top: 50%; left: 50%; transform: translate(-50%, -46%);
  width: min(920px, calc(100% - 36px)); max-height: calc(100dvh - 48px); overflow: auto;
  background: var(--paper); padding: 34px 38px 38px; opacity: 0; visibility: hidden;
  transition: opacity .25s, transform .25s, visibility .25s; box-shadow: 0 30px 80px #00000042;
}
.checkout-modal.open { opacity: 1; visibility: visible; transform: translate(-50%, -50%); }
.checkout-head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 1px solid var(--line); padding-bottom: 21px; }
.checkout-head .eyebrow { font-size: 8px; }
.checkout-head h2 { font: 700 38px/.9 var(--display); letter-spacing: -.07em; margin: 13px 0 0; }
.checkout-head h2 span { color: var(--red); }
.checkout-grid { display: grid; grid-template-columns: .92fr 1.08fr; gap: 42px; padding-top: 25px; }
.checkout-summary .eyebrow, .checkout-form > .eyebrow { font-size: 8px; }
.checkout-lines { margin-top: 13px; border-top: 1px solid var(--line); }
.checkout-line { display: grid; grid-template-columns: 53px 1fr auto; gap: 11px; padding: 11px 0; border-bottom: 1px solid var(--line); align-items: center; }
.checkout-line img { width: 53px; height: 64px; object-fit: cover; background: #ddd; }
.checkout-line b { display: block; font: 600 10.5px var(--display); margin-bottom: 4px; }
.checkout-line span { font: 7px var(--mono); color: var(--muted); letter-spacing: .02em; }
.checkout-line strong { font: 10px var(--mono); font-weight: 400; }
.checkout-totals { padding: 16px 0 0; font: 9px var(--mono); }
.checkout-totals > div { display: flex; justify-content: space-between; margin-bottom: 9px; color: var(--muted); }
.checkout-totals b { font-weight: 500; color: var(--ink); }
.checkout-totals .checkout-total { border-top: 1px solid var(--ink); margin-top: 13px; padding-top: 12px; color: var(--ink); font-size: 10px; }
.checkout-totals .checkout-total b { font-size: 15px; }
.checkout-secure { font: 7px/1.5 var(--mono); color: var(--muted); margin: 17px 0 0; letter-spacing: .02em; }
.checkout-form { border-left: 1px solid var(--line); padding-left: 36px; }
.checkout-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 13px; margin-top: 13px; }
.checkout-fields label { display: flex; flex-direction: column; gap: 5px; font: 7.5px var(--mono); letter-spacing: .04em; color: var(--muted); }
.checkout-fields .span-2 { grid-column: span 2; }
.checkout-fields input {
  border: 1px solid var(--line); background: #fffdf8; padding: 10px; font: 12px var(--display);
  outline: 0; border-radius: 0; color: var(--ink); width: 100%;
}
.checkout-fields input:focus { border-color: var(--ink); }
.checkout-payment-label { display: flex; gap: 7px; align-items: center; margin: 22px 0 9px; }
.checkout-payment-label i { font-style: normal; background: var(--green); color: var(--ink); padding: 2px 4px; font-size: 6px; }
.payment-options { display: flex; gap: 7px; }
.payment-options label { flex: 1; position: relative; cursor: pointer; }
.payment-options input { position: absolute; opacity: 0; }
.payment-options span {
  display: block; border: 1px solid var(--line); padding: 10px 4px; text-align: center;
  font: 8px var(--mono); transition: .18s;
}
.payment-options input:checked + span { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.checkout-error { background: #f7d9d2; color: #952f1e; padding: 8px 10px; font: 8px var(--mono); margin: 12px 0 0; }
.checkout-error[hidden] { display: none; }
.checkout-submit { width: 100%; margin-top: 17px; justify-content: space-between; }
.checkout-success { text-align: center; padding: 42px 20px 26px; max-width: 520px; margin: auto; }
.checkout-success-star { display: block; color: var(--red); font-size: 40px; margin-bottom: 12px; }
.checkout-success h3 { font: 700 45px/.9 var(--display); letter-spacing: -.07em; margin: 16px 0 15px; }
.checkout-success h3 span { color: var(--red); }
.checkout-success p { font-size: 12px; line-height: 1.8; color: var(--muted); }
.checkout-success-actions { display: flex; gap: 9px; justify-content: center; margin-top: 22px; flex-wrap: wrap; }

/* ---------- página minha conta ---------- */
.account-page { background: var(--paper); }
.account-header-actions { display: flex; align-items: center; gap: 18px; }
.account-header-link { font: 9px var(--mono); letter-spacing: .05em; border-bottom: 1px solid var(--ink); padding-bottom: 3px; }
.account-shell { min-height: 65vh; }
.account-hero { background: var(--ink); color: var(--paper); padding: 62px 6.1% 0; overflow: hidden; position: relative; }
.account-hero:after {
  content: '98'; position: absolute; right: 1%; bottom: -60px; font: 700 300px/.8 var(--display);
  letter-spacing: -.1em; color: #ffffff06; pointer-events: none;
}
.account-hero-inner { display: flex; align-items: flex-end; justify-content: space-between; gap: 35px; position: relative; z-index: 1; padding-bottom: 37px; }
.account-hero .eyebrow { color: var(--green); font-size: 9px; }
.account-hero h1 { font: 700 clamp(48px, 6.4vw, 87px)/.86 var(--display); letter-spacing: -.08em; margin: 22px 0 0; }
.account-hero h1 span { color: var(--red); }
.account-hero p { font-size: 12px; color: #b9b8b1; margin: 18px 0 0; max-width: 370px; line-height: 1.65; }
.account-identity { display: flex; align-items: center; gap: 15px; min-width: 240px; padding-bottom: 4px; }
.account-avatar-lg {
  width: 63px; height: 63px; border-radius: 50%; border: 1px solid #ffffff45; display: grid;
  place-items: center; font: 600 21px var(--display); color: var(--green); flex: none;
}
.account-identity-info { display: flex; flex-direction: column; gap: 4px; }
.account-identity-info b { font: 600 14px var(--display); }
.account-identity-info span { font: 8px var(--mono); color: #a8a79f; }
.account-identity .account-logout-link {
  border: 1px solid #ffffff3b; background: none; color: var(--paper); padding: 9px 11px;
  font: 7px var(--mono); letter-spacing: .04em; cursor: pointer; margin-left: auto;
}
.account-identity .account-logout-link:hover { background: var(--red); border-color: var(--red); }
.account-stats { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid #ffffff24; position: relative; z-index: 1; }
.account-stat { padding: 19px 0 22px; border-right: 1px solid #ffffff1c; display: flex; align-items: baseline; gap: 11px; }
.account-stat:last-child { border-right: 0; }
.account-stat b { font: 600 28px var(--display); letter-spacing: -.055em; }
.account-stat span { font: 8px var(--mono); color: #9f9e96; letter-spacing: .04em; }
.account-stat b.green { color: var(--green); }
.account-main { padding: 38px 6.1% 90px; display: grid; grid-template-columns: 185px 1fr; gap: 44px; align-items: start; }
.account-nav { display: flex; flex-direction: column; position: sticky; top: 20px; }
.account-nav button {
  text-align: left; background: none; border: 0; border-bottom: 1px solid var(--line);
  padding: 14px 4px; font: 9px var(--mono); letter-spacing: .05em; cursor: pointer; color: var(--muted);
  display: flex; justify-content: space-between; align-items: center;
}
.account-nav button span { font-size: 8px; color: #aaa89e; }
.account-nav button:hover { color: var(--ink); }
.account-nav button.active { color: var(--ink); border-bottom-color: var(--ink); }
.account-nav button.active:before { content: '↗'; color: var(--red); margin-right: 6px; }
.account-nav .admin-nav-link { color: var(--red); text-decoration: none; }
.account-pane { min-height: 300px; }
.account-pane[hidden] { display: none; }
.account-pane-title { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 21px; }
.account-pane-title h2 { font: 700 30px/.95 var(--display); letter-spacing: -.055em; margin: 0; }
.account-pane-title p { font: 9px var(--mono); color: var(--muted); margin: 7px 0 0; }
.account-pane-title .text-link { font-size: 8px; }
.account-welcome { background: #e9e6dc; padding: 25px 27px; margin-bottom: 22px; display: flex; justify-content: space-between; gap: 20px; align-items: center; }
.account-welcome h3 { font: 600 19px/1.15 var(--display); letter-spacing: -.035em; margin: 0 0 6px; }
.account-welcome p { font-size: 11px; line-height: 1.55; color: var(--muted); margin: 0; max-width: 460px; }
.account-welcome .button { flex: none; min-height: 42px; font-size: 8px; }
.account-order { border: 1px solid var(--line); margin-bottom: 13px; background: #f7f5ee; }
.account-order-head { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 14px 17px; border-bottom: 1px solid var(--line); }
.account-order-number { font: 600 12px var(--display); letter-spacing: -.01em; }
.account-order-date { font: 7.5px var(--mono); color: var(--muted); display: block; margin-top: 4px; }
.order-status { padding: 6px 8px; font: 7px var(--mono); letter-spacing: .04em; background: #dedbd1; white-space: nowrap; }
.order-status.pago { background: var(--green); }
.order-status.enviado { background: #c9d9e8; }
.order-status.entregue { background: var(--ink); color: var(--paper); }
.order-status.cancelado { background: #f0c8bf; color: #8d2c1b; }
.account-order-body { padding: 4px 17px; }
.account-order-item { display: grid; grid-template-columns: 42px 1fr auto; gap: 11px; align-items: center; padding: 10px 0; border-bottom: 1px solid #e2dfd6; }
.account-order-item:last-child { border-bottom: 0; }
.account-order-item img { width: 42px; height: 51px; object-fit: cover; background: #ddd; }
.account-order-item b { display: block; font: 600 10px var(--display); }
.account-order-item span { font: 7px var(--mono); color: var(--muted); }
.account-order-item strong { font: 9px var(--mono); font-weight: 400; }
.account-order-foot { display: flex; justify-content: space-between; padding: 11px 17px; border-top: 1px solid var(--line); font: 9px var(--mono); }
.account-order-foot b { font-size: 12px; }
.account-empty { border: 1px dashed var(--line); padding: 45px 25px; text-align: center; color: var(--muted); }
.account-empty span { display: block; color: var(--red); font-size: 29px; margin-bottom: 12px; }
.account-empty h3 { font: 600 22px/.95 var(--display); letter-spacing: -.05em; color: var(--ink); margin: 0 0 9px; }
.account-empty p { font-size: 11px; margin: 0 0 18px; }
.favorite-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 19px; }
.favorite-card { border: 1px solid var(--line); background: #f7f5ee; }
.favorite-card img { width: 100%; height: 210px; object-fit: cover; display: block; }
.favorite-card-info { padding: 12px; }
.favorite-card-info h3 { font: 600 11px var(--display); margin: 0 0 4px; }
.favorite-card-info span { font: 8px var(--mono); color: var(--muted); }
.favorite-card-actions { display: flex; justify-content: space-between; align-items: center; margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--line); }
.favorite-card-actions a, .favorite-card-actions button { background: none; border: 0; padding: 0; font: 7.5px var(--mono); letter-spacing: .03em; cursor: pointer; border-bottom: 1px solid; }
.favorite-card-actions button { color: var(--red); border-color: transparent; }
.account-card { border: 1px solid var(--line); padding: 23px 25px; margin-bottom: 17px; background: #f8f6ef; }
.account-card h3 { font: 600 17px var(--display); letter-spacing: -.035em; margin: 0 0 4px; }
.account-card > p { font-size: 10px; line-height: 1.6; color: var(--muted); margin: 0 0 18px; }
.account-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 15px; }
.account-form-grid label { display: flex; flex-direction: column; gap: 5px; font: 7.5px var(--mono); letter-spacing: .04em; color: var(--muted); }
.account-form-grid .span-2 { grid-column: span 2; }
.account-form-grid input {
  border: 1px solid var(--line); background: #fffdf8; padding: 10px; font: 12px var(--display);
  outline: 0; border-radius: 0; width: 100%; color: var(--ink);
}
.account-form-grid input:focus { border-color: var(--ink); }
.account-form-grid input:disabled { background: #ece9e0; color: var(--muted); }
.account-card-actions { display: flex; align-items: center; gap: 14px; margin-top: 16px; flex-wrap: wrap; }
.account-card-actions .button { min-height: 44px; font-size: 8px; }
.account-inline-message { font: 8px var(--mono); color: var(--green); }
.account-inline-message.error { color: var(--red); }
.account-guest { min-height: 68vh; display: grid; place-items: center; padding: 55px 6%; }
.account-guest-card { max-width: 560px; text-align: center; }
.account-guest-card .eyebrow { justify-content: center; }
.account-guest-card h1 { font: 700 clamp(45px, 7vw, 76px)/.87 var(--display); letter-spacing: -.08em; margin: 23px 0 17px; }
.account-guest-card h1 span { color: var(--red); }
.account-guest-card p { font-size: 12px; line-height: 1.7; color: var(--muted); max-width: 390px; margin: 0 auto 25px; }
.account-guest-actions { display: flex; gap: 9px; justify-content: center; flex-wrap: wrap; }
.account-admin-note { margin-top: 32px; font: 8px var(--mono); color: var(--muted); }
.account-admin-note a { text-decoration: underline; }

@media (max-width: 1000px) {
  .account-label { display: none; }
  .account-main { grid-template-columns: 150px 1fr; gap: 27px; }
  .favorite-grid { grid-template-columns: repeat(2, 1fr); }
  .checkout-grid { grid-template-columns: 1fr; gap: 25px; }
  .checkout-form { border-left: 0; border-top: 1px solid var(--line); padding-left: 0; padding-top: 24px; }
