@media (max-width: 700px) {
  .auth-modal { padding: 31px 23px 20px; }
  .auth-title { font-size: 38px; }
  .auth-trust { margin: 20px -23px -20px; }
  .checkout-modal { padding: 26px 20px 28px; max-height: calc(100dvh - 22px); width: calc(100% - 20px); }
  .checkout-head h2 { font-size: 32px; }
  .checkout-fields { gap: 10px; }
  .checkout-success h3 { font-size: 37px; }
  .toolbar-right { gap: 9px; flex-direction: column; align-items: flex-end; }
  .collection-select-wrap span { display: none; }
  .account-hero { padding: 43px 6% 0; }
  .account-hero-inner { display: block; padding-bottom: 26px; }
