  .account-hero p { font-size: 11px; }
  .account-identity { margin-top: 23px; min-width: 0; }
  .account-avatar-lg { width: 51px; height: 51px; font-size: 17px; }
  .account-stats { grid-template-columns: 1fr 1fr; }
  .account-stat { padding: 14px 0; }
  .account-stat:nth-child(2) { border-right: 0; }
  .account-stat b { font-size: 23px; }
  .account-main { display: block; padding: 22px 5% 65px; }
  .account-nav { flex-direction: row; overflow-x: auto; position: static; margin-bottom: 25px; border-bottom: 1px solid var(--line); }
  .account-nav button { border-bottom: 2px solid transparent; white-space: nowrap; padding: 11px 9px; }
  .account-nav button.active { border-bottom-color: var(--ink); }
