input.content:
/* RUA 98 — painel administrativo */
:root {
  --paper: #f1efe8; --ink: #171816; --muted: #77776f; --red: #e44d32;
  --line: #d5d3ca; --green: #d6e363; --white: #fffdf8;
  --mono: 'DM Mono', monospace; --sans: 'DM Sans', sans-serif; --display: 'Space Grotesk', sans-serif;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; }
.admin-body {
  background: #eceae2; color: var(--ink); font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
}
button, input, select, textarea { font: inherit; color: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; }
[hidden] { display: none !important; }
.admin-eyebrow {
  display: inline-flex; align-items: center; gap: 8px; font: 8px var(--mono);
  letter-spacing: .07em; color: var(--muted); text-transform: uppercase;
}
.eyebrow-line { width: 22px; height: 1px; background: var(--red); display: inline-block; }
.admin-wordmark {
  font: 700 31px/.9 var(--display); letter-spacing: -.09em; position: relative; display: inline-block;
}
.admin-wordmark span { color: var(--red); }
.admin-wordmark i { font: 8px var(--mono); position: absolute; right: -10px; top: -2px; font-style: normal; }

/* ---------- login ---------- */
.admin-login { min-height: 100dvh; display: grid; grid-template-columns: 1.1fr .9fr; }
.login-brand {
  background: var(--ink); color: var(--paper); padding: 43px 6vw 30px; display: flex;
  flex-direction: column; position: relative; overflow: hidden;
}
.login-brand:after {
  content: '98'; position: absolute; right: -2%; bottom: -100px; font: 700 420px/.8 var(--display);
  letter-spacing: -.12em; color: #ffffff06; pointer-events: none;
}
.login-brand > * { position: relative; z-index: 1; }
.login-brand-copy { margin: auto 0; padding: 55px 0 40px; }
.login-brand .admin-eyebrow { color: var(--green); }
.login-brand h1 {
  font: 700 clamp(64px, 8.5vw, 112px)/.83 var(--display); letter-spacing: -.095em;
  margin: 26px 0 21px;
}
.login-brand h1 span { color: var(--red); }
.login-brand p { max-width: 360px; font-size: 13px; line-height: 1.7; color: #b9b8b1; margin: 0; }
.login-brand-foot {
  display: flex; align-items: center; gap: 18px; border-top: 1px solid #ffffff26; padding-top: 17px;
  font: 8px var(--mono); letter-spacing: .06em; color: #a6a59d;
}
.login-brand-foot span:first-child { color: var(--red); font-size: 15px; }
.login-brand-foot span:last-child { margin-left: auto; }
.login-panel {
  display: flex; flex-direction: column; justify-content: center; padding: 55px 7vw;
  position: relative; background: var(--paper);
}
.login-back {
  position: absolute; top: 30px; right: 7vw; font: 8px var(--mono); letter-spacing: .045em;
  border-bottom: 1px solid var(--ink); padding-bottom: 4px;
}
.login-form-wrap { width: 100%; max-width: 370px; margin: auto; }
.login-panel h2 { font: 700 clamp(43px, 4.7vw, 58px)/.88 var(--display); letter-spacing: -.075em; margin: 20px 0 15px; }
.login-panel h2 span { color: var(--red); }
.login-intro { font-size: 11.5px; line-height: 1.6; color: var(--muted); margin: 0 0 22px; max-width: 290px; }
.login-session-note {
  background: #e6e2d4; border-left: 2px solid var(--red); padding: 10px 12px;
  font: 8px/1.6 var(--mono); margin-bottom: 16px;
}
.login-session-note button {
  border: 0; background: none; padding: 0; margin-top: 4px; text-decoration: underline;
  font: 8px var(--mono); color: var(--red);
}
#admin-login-form { display: flex; flex-direction: column; }
#admin-login-form label {
  display: flex; flex-direction: column; gap: 6px; margin-bottom: 13px;
  font: 8px var(--mono); letter-spacing: .055em;
}
#admin-login-form input {
  border: 1px solid var(--line); background: var(--white); padding: 12px 11px;
  font: 14px var(--display); outline: 0; border-radius: 0;
}
#admin-login-form input:focus { border-color: var(--ink); }
.login-error { background: #f5d4cc; color: #922d1b; padding: 9px 11px; margin: 1px 0 12px; font: 8.5px/1.5 var(--mono); }
.login-submit { width: 100%; justify-content: space-between; margin-top: 3px; }
.login-demo {
  display: block; margin: 12px auto 0; border: 0; background: none; text-decoration: underline;
  font: 8px var(--mono); color: var(--muted); letter-spacing: .04em;
}
.login-demo:hover { color: var(--red); }
.login-credentials {
  margin-top: 25px; background: #e7e3d7; padding: 13px 14px; display: flex; flex-direction: column; gap: 4px;
  font: 8px var(--mono); color: var(--muted);
}
.login-credentials span { color: var(--red); letter-spacing: .05em; margin-bottom: 2px; }
.login-credentials b { font-weight: 500; color: var(--ink); font-size: 9px; }
.login-credentials p { margin: 5px 0 0; line-height: 1.6; font-size: 7px; }

/* ---------- shell ---------- */
.admin-app { min-height: 100dvh; }
.admin-sidebar {
  width: 236px; background: var(--ink); color: var(--paper); position: fixed; inset: 0 auto 0 0;
  z-index: 50; display: flex; flex-direction: column; padding: 25px 17px 16px;
}
.sidebar-brand { display: flex; align-items: baseline; justify-content: space-between; padding: 0 6px 25px; border-bottom: 1px solid #ffffff22; }
.sidebar-brand .admin-wordmark { font-size: 28px; color: var(--paper); }
.sidebar-brand > span { font: 6.5px var(--mono); letter-spacing: .08em; color: #8e8d86; }
.admin-nav { padding-top: 8px; overflow-y: auto; flex: 1; }
.nav-label { display: block; font: 6.5px var(--mono); letter-spacing: .1em; color: #77766f; padding: 15px 11px 7px; }
.nav-label-two { margin-top: 8px; border-top: 1px solid #ffffff12; padding-top: 17px; }
.admin-nav button {
  width: 100%; display: flex; align-items: center; gap: 10px; padding: 10px 11px; border: 0;
  border-left: 2px solid transparent; background: none; color: #b3b2aa; font: 8.5px var(--mono);
  letter-spacing: .04em; text-align: left; transition: background .15s, color .15s;
}
.admin-nav button:hover { background: #ffffff08; color: var(--paper); }
.admin-nav button.active { background: #ffffff0e; color: var(--paper); border-left-color: var(--green); }
.nav-icon { width: 13px; text-align: center; color: #76756e; font-size: 10px; }
.admin-nav button.active .nav-icon { color: var(--green); }
.nav-badge { margin-left: auto; background: var(--red); color: white; font: 6.5px var(--mono); padding: 2px 5px; border-radius: 10px; }
.sidebar-foot { border-top: 1px solid #ffffff22; padding-top: 11px; }
.sidebar-foot a, .sidebar-foot button {
  display: block; width: 100%; background: none; border: 0; color: #b3b2aa; padding: 9px 5px;
  font: 7.5px var(--mono); letter-spacing: .04em; text-align: left;
}
.sidebar-foot a:hover, .sidebar-foot button:hover { color: var(--green); }
.admin-shell { margin-left: 236px; min-height: 100dvh; display: flex; flex-direction: column; }
.admin-topbar {
  height: 92px; flex: none; background: var(--paper); border-bottom: 1px solid var(--line);
  padding: 0 33px; display: flex; align-items: center; gap: 18px; position: sticky; top: 0; z-index: 30;
}
.topbar-title { display: flex; flex-direction: column; gap: 7px; }
.topbar-title .admin-eyebrow { font-size: 7px; }
.topbar-title h1 { font: 700 24px var(--display); letter-spacing: -.05em; margin: 0; }
.admin-user { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.admin-user-avatar {
  width: 34px; height: 34px; border-radius: 50%; background: var(--ink); color: var(--green);
  display: grid; place-items: center; font: 600 11px var(--display);
}
.admin-user div { display: flex; flex-direction: column; gap: 3px; }
.admin-user b { font: 600 10px var(--display); }
.admin-user span:last-child { font: 6.5px var(--mono); color: var(--muted); letter-spacing: .05em; }
.mobile-nav-toggle { display: none; background: none; border: 1px solid var(--line); width: 34px; height: 34px; font-size: 15px; }
.admin-sidebar-scrim { display: none; }
.admin-content { padding: 29px 33px 60px; flex: 1; }
.admin-panel { animation: panelIn .25s ease both; }
@keyframes panelIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }

/* ---------- títulos ---------- */
.panel-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 18px; flex-wrap: wrap; margin-bottom: 18px; }
.panel-heading h2 { font: 700 34px/.92 var(--display); letter-spacing: -.065em; margin: 0; }
.panel-heading h2 span { color: var(--red); }
.panel-heading p { font: 8px var(--mono); color: var(--muted); margin: 7px 0 0; letter-spacing: .03em; }
.panel-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.admin-button {
  min-height: 39px; padding: 0 14px; border: 1px solid var(--ink); background: transparent;
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  font: 8px var(--mono); letter-spacing: .04em; transition: .18s;
}
.admin-button:hover { background: var(--ink); color: var(--paper); }
.admin-button-dark { background: var(--ink); color: var(--paper); }
.admin-button-dark:hover { background: var(--red); border-color: var(--red); }
.admin-button-green { background: var(--green); border-color: var(--green); }
.admin-button-green:hover { background: var(--ink); border-color: var(--ink); color: var(--paper); }
.admin-button-danger { color: var(--red); border-color: #d8a79e; }
.admin-button-danger:hover { background: var(--red); border-color: var(--red); color: white; }
.admin-button.small { min-height: 29px; padding: 0 9px; font-size: 7px; gap: 5px; }
.admin-button:disabled { opacity: .55; cursor: wait; }

/* ---------- dashboard ---------- */
.admin-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 18px; }
.kpi { background: var(--white); border: 1px solid var(--line); padding: 17px 18px 15px; position: relative; overflow: hidden; }
.kpi .kpi-label { display: block; font: 7px var(--mono); letter-spacing: .06em; color: var(--muted); margin-bottom: 12px; }
.kpi b { font: 600 30px/.9 var(--display); letter-spacing: -.06em; }
.kpi small { display: block; font: 7px var(--mono); color: var(--muted); margin-top: 10px; letter-spacing: .02em; }
.kpi-mark { position: absolute; right: 10px; top: 8px; color: #e1ded3; font-size: 22px; }
.kpi.dark { background: var(--ink); border-color: var(--ink); color: var(--paper); }
.kpi.dark .kpi-label, .kpi.dark small { color: #9f9e96; }
.kpi.dark b { color: var(--green); }
.kpi.dark .kpi-mark { color: #ffffff1e; }
.kpi.accent { background: var(--green); border-color: var(--green); }
.kpi.accent .kpi-label, .kpi.accent small { color: #5c6035; }
.kpi.accent .kpi-mark { color: #72773a4a; }
.dash-grid { display: grid; grid-template-columns: 1.5fr .85fr; gap: 16px; align-items: start; }
.dash-col { display: flex; flex-direction: column; gap: 16px; }
.admin-card { background: var(--white); border: 1px solid var(--line); }
.admin-card-head { padding: 15px 17px; border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.admin-card-head h3 { font: 600 15px var(--display); letter-spacing: -.03em; margin: 0; }
.admin-card-head span, .admin-card-head a { font: 7px var(--mono); color: var(--muted); letter-spacing: .03em; }
.admin-card-head a { border-bottom: 1px solid var(--line); padding-bottom: 2px; }
.admin-card-head a:hover { color: var(--red); }
.admin-card-body { padding: 15px 17px; }
.alert-list { display: flex; flex-direction: column; }
.alert-item { display: flex; align-items: center; gap: 10px; padding: 9px 0; border-bottom: 1px solid #e9e6dd; }
.alert-item:last-child { border-bottom: 0; padding-bottom: 0; }
.alert-item img { width: 34px; height: 40px; object-fit: cover; background: #ddd; }
.alert-item div { min-width: 0; }
.alert-item b { display: block; font: 600 10px var(--display); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.alert-item span { font: 7px var(--mono); color: var(--muted); }
.alert-item strong { margin-left: auto; font: 9px var(--mono); color: var(--red); white-space: nowrap; }
.alert-empty { font: 8px/1.7 var(--mono); color: var(--muted); padding: 8px 0; }
.drop-mini { background: var(--ink); color: var(--paper); padding: 17px; }
.drop-mini .admin-eyebrow { color: var(--green); font-size: 6.5px; }
.drop-mini h3 { font: 600 22px/.95 var(--display); letter-spacing: -.055em; margin: 12px 0 8px; }
.drop-mini p { font-size: 10px; line-height: 1.55; color: #aaa9a1; margin: 0 0 13px; }
.drop-mini .drop-meta { display: flex; justify-content: space-between; font: 7px var(--mono); color: #c4c3bb; border-top: 1px solid #ffffff24; padding-top: 10px; }
.drop-mini .drop-meta b { color: var(--green); font-weight: 500; }
.quick-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.quick-actions button {
  border: 1px solid var(--line); background: none; padding: 12px 9px; text-align: left;
  font: 7.5px var(--mono); letter-spacing: .025em; transition: .15s;
}
.quick-actions button:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.quick-actions button b { display: block; font-size: 15px; margin-bottom: 5px; color: var(--red); }

/* ---------- tabelas ---------- */
.table-wrap { background: var(--white); border: 1px solid var(--line); overflow: auto; }
.admin-table { width: 100%; border-collapse: collapse; min-width: 700px; }
.admin-table th {
  padding: 11px 14px; text-align: left; background: #f4f2ea; border-bottom: 1px solid var(--line);
  font: 6.5px var(--mono); letter-spacing: .06em; color: var(--muted); white-space: nowrap;
}
.admin-table td { padding: 11px 14px; border-bottom: 1px solid #e9e6dd; font-size: 10.5px; vertical-align: middle; }
.admin-table tr:last-child td { border-bottom: 0; }
.admin-table tbody tr:hover { background: #faf8f2; }
.table-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.admin-search { display: flex; align-items: center; gap: 7px; border: 1px solid var(--line); background: var(--white); padding: 0 10px; }
.admin-search span { color: var(--muted); font-size: 11px; }
.admin-search input { border: 0; outline: 0; background: none; padding: 9px 0; width: 220px; font: 10px var(--display); }
.admin-filter {
  border: 1px solid var(--line); background: var(--white); padding: 9px 10px; border-radius: 0;
  font: 7.5px var(--mono); outline: 0; cursor: pointer;
}
.table-count { font: 7px var(--mono); color: var(--muted); }
.row-product { display: flex; align-items: center; gap: 10px; }
.row-product img { width: 38px; height: 46px; object-fit: cover; background: #ddd; flex: none; }
.row-product div { min-width: 0; }
.row-product b { display: block; font: 600 10.5px var(--display); margin-bottom: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 190px; }
.row-product span { font: 6.5px var(--mono); color: var(--muted); letter-spacing: .015em; }
.row-actions { display: flex; gap: 5px; justify-content: flex-end; }
.icon-action {
  width: 27px; height: 27px; border: 1px solid var(--line); background: none; display: grid;
  place-items: center; font-size: 9px; transition: .15s;
}
.icon-action:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.icon-action.danger:hover { background: var(--red); border-color: var(--red); color: white; }
.badge {
  display: inline-block; padding: 4px 7px; background: #e7e4da; font: 6.5px var(--mono);
  letter-spacing: .035em; white-space: nowrap;
}
.badge.active, .badge.pago { background: var(--green); }
.badge.ativo { background: var(--green); }
.badge.inactive, .badge.encerrado { background: #ddd9ce; color: #77766f; }
.badge.agendado { background: #cbd9e9; }
.badge.pendente { background: #f2e2ab; }
.badge.enviado { background: #cbd9e9; }
.badge.entregue { background: var(--ink); color: var(--paper); }
.badge.cancelado { background: #f0c8bf; color: #8d2c1b; }
.badge.blocked { background: #f0c8bf; color: #8d2c1b; }
.badge.admin { background: var(--ink); color: var(--green); }
.status-select {
  border: 1px solid var(--line); background: var(--white); font: 7px var(--mono);
  padding: 6px 5px; border-radius: 0; outline: 0; cursor: pointer;
}
.stock-low { color: var(--red); }
.stock-ok { color: var(--muted); }
.cell-muted { color: var(--muted); font-size: 8px; font-family: var(--mono); }
.customer-cell b { display: block; font: 600 10.5px var(--display); margin-bottom: 3px; }
.customer-cell span { font: 7px var(--mono); color: var(--muted); }
.empty-row { text-align: center; padding: 36px 20px !important; color: var(--muted); font: 8px var(--mono); }

/* ---------- cards de coleção / drop ---------- */
.collection-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 13px; }
.collection-card { background: var(--white); border: 1px solid var(--line); padding: 18px; display: flex; flex-direction: column; min-height: 172px; }
.collection-card-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.collection-card h3 { font: 600 21px/.95 var(--display); letter-spacing: -.05em; margin: 10px 0 7px; }
.collection-card p { font-size: 10px; line-height: 1.55; color: var(--muted); margin: 0 0 14px; }
.collection-card .collection-meta { margin-top: auto; display: flex; align-items: center; justify-content: space-between; border-top: 1px solid #e9e6dd; padding-top: 11px; font: 7px var(--mono); color: var(--muted); }
.collection-card .collection-actions { display: flex; gap: 5px; margin-top: 11px; }
.drop-card .drop-date { font: 7.5px var(--mono); color: var(--muted); letter-spacing: .03em; }
.drop-products { display: flex; gap: 5px; margin-top: 2px; }
.drop-products img { width: 27px; height: 33px; object-fit: cover; background: #ddd; }
.drop-products span { font: 7px var(--mono); color: var(--muted); align-self: center; margin-left: 3px; }

/* ---------- modais ---------- */
.admin-modal-scrim { position: fixed; inset: 0; background: #10110f9e; z-index: 70; backdrop-filter: blur(2px); }
.admin-modal {
  position: fixed; z-index: 71; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: min(680px, calc(100% - 26px)); max-height: calc(100dvh - 34px); background: var(--paper);
  box-shadow: 0 30px 80px #00000042; display: flex; flex-direction: column; overflow: hidden;
  animation: modalIn .2s ease both;
}
.admin-modal.wide { width: min(880px, calc(100% - 26px)); }
@keyframes modalIn { from { opacity: 0; transform: translate(-50%, -47%); } }
.admin-modal-open { overflow: hidden; }
.form-head { padding: 19px 23px; border-bottom: 1px solid var(--line); display: flex; justify-content: space-between; align-items: flex-start; gap: 15px; }
.form-head .admin-eyebrow { font-size: 6.5px; }
.form-head h2 { font: 700 27px/.95 var(--display); letter-spacing: -.06em; margin: 9px 0 0; }
.form-head h2 span { color: var(--red); }
.modal-close { border: 0; background: none; font: 300 29px/1 var(--display); padding: 0; }
.form-scroll { padding: 20px 23px; overflow: auto; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 13px; }
.form-grid label { display: flex; flex-direction: column; gap: 5px; font: 7px var(--mono); letter-spacing: .04em; color: var(--muted); }
.form-grid .span-2 { grid-column: span 2; }
.form-grid input, .form-grid select, .form-grid textarea {
  width: 100%; border: 1px solid var(--line); background: var(--white); padding: 9px 10px;
  font: 11.5px var(--display); outline: 0; border-radius: 0; color: var(--ink);
}
.form-grid input:focus, .form-grid select:focus, .form-grid textarea:focus { border-color: var(--ink); }
.form-grid textarea { min-height: 82px; resize: vertical; line-height: 1.5; }
.form-image-row { display: grid; grid-template-columns: 1fr 64px; gap: 10px; align-items: end; }
.form-image-row img { width: 64px; height: 74px; object-fit: cover; background: #ddd; }
.form-checks { display: flex; gap: 17px; flex-wrap: wrap; align-items: center; padding: 3px 0; }
.form-checks label { flex-direction: row; align-items: center; gap: 6px; font: 7.5px var(--mono); color: var(--ink); cursor: pointer; }
.form-checks input { width: 13px; height: 13px; accent-color: var(--red); }
.form-error { background: #f5d4cc; color: #922d1b; padding: 9px 11px; font: 8px/1.5 var(--mono); margin: 13px 0 0; }
.form-actions { padding: 13px 23px; border-top: 1px solid var(--line); display: flex; justify-content: flex-end; gap: 8px; background: var(--paper); }
.checkbox-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; max-height: 170px; overflow: auto; padding: 8px; border: 1px solid var(--line); background: var(--white); }
.checkbox-grid label { display: flex; align-items: center; gap: 7px; font: 8px var(--display); padding: 5px; border: 1px solid transparent; cursor: pointer; }
.checkbox-grid label:hover { border-color: var(--line); }
.checkbox-grid input { accent-color: var(--red); }
.confirm-copy { padding: 25px 23px 4px; }
.confirm-copy h3 { font: 600 23px/.95 var(--display); letter-spacing: -.05em; margin: 0 0 9px; }
.confirm-copy p { font-size: 11px; line-height: 1.65; color: var(--muted); margin: 0; }
.admin-modal .confirm-actions { padding: 19px 23px 23px; display: flex; justify-content: flex-end; gap: 8px; }

/* ---------- detalhe do pedido ---------- */
.order-detail { padding: 20px 23px; overflow: auto; }
.order-detail-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 15px; margin-bottom: 17px; }
.order-detail-top h2 { font: 700 26px var(--display); letter-spacing: -.05em; margin: 0 0 5px; }
.order-detail-top span { font: 7.5px var(--mono); color: var(--muted); }
.order-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 17px; }
.order-info { border: 1px solid var(--line); background: var(--white); padding: 12px 13px; }
.order-info b { display: block; font: 6.5px var(--mono); letter-spacing: .05em; color: var(--muted); margin-bottom: 7px; }
.order-info span { display: block; font-size: 10px; line-height: 1.55; }
.order-items { border: 1px solid var(--line); background: var(--white); }
.order-item { display: grid; grid-template-columns: 40px 1fr auto; gap: 10px; align-items: center; padding: 9px 12px; border-bottom: 1px solid #e9e6dd; }
.order-item:last-child { border-bottom: 0; }
.order-item img { width: 40px; height: 48px; object-fit: cover; background: #ddd; }
.order-item b { display: block; font: 600 10px var(--display); }
.order-item span { font: 7px var(--mono); color: var(--muted); }
.order-item strong { font: 9px var(--mono); font-weight: 400; }
.order-totals { display: flex; flex-direction: column; gap: 6px; margin-top: 13px; font: 8.5px var(--mono); }
.order-totals div { display: flex; justify-content: space-between; color: var(--muted); }
.order-totals b { color: var(--ink); font-weight: 500; }
.order-totals .grand { border-top: 1px solid var(--ink); padding-top: 9px; color: var(--ink); font-size: 11px; }
.order-detail-actions { display: flex; justify-content: space-between; align-items: center; border-top: 1px solid var(--line); padding: 14px 23px; gap: 12px; flex-wrap: wrap; }
.order-detail-actions label { display: flex; align-items: center; gap: 7px; font: 7px var(--mono); color: var(--muted); }

/* ---------- configurações ---------- */
.settings-grid { display: grid; grid-template-columns: 1.25fr .75fr; gap: 16px; align-items: start; }
.settings-col { display: flex; flex-direction: column; gap: 16px; }
.settings-card { background: var(--white); border: 1px solid var(--line); }
.settings-card-head { padding: 15px 17px; border-bottom: 1px solid var(--line); }
.settings-card-head h3 { font: 600 16px var(--display); letter-spacing: -.035em; margin: 0 0 4px; }
.settings-card-head p { font: 8px var(--mono); color: var(--muted); margin: 0; }
.settings-form { padding: 16px 17px; display: grid; grid-template-columns: 1fr 1fr; gap: 11px 12px; }
.settings-form label { display: flex; flex-direction: column; gap: 5px; font: 7px var(--mono); color: var(--muted); letter-spacing: .035em; }
.settings-form .span-2 { grid-column: span 2; }
.settings-form input, .settings-form textarea {
  border: 1px solid var(--line); background: var(--white); padding: 9px 10px; font: 11px var(--display);
  outline: 0; border-radius: 0; width: 100%; color: var(--ink);
}
.settings-form input:focus, .settings-form textarea:focus { border-color: var(--ink); }
.settings-form textarea { min-height: 65px; resize: vertical; }
.settings-actions { padding: 0 17px 16px; display: flex; align-items: center; gap: 10px; }
.settings-message { font: 7.5px var(--mono); color: #5b621f; }
.team-list { display: flex; flex-direction: column; padding: 5px 17px 10px; }
.team-member { display: flex; align-items: center; gap: 9px; padding: 9px 0; border-bottom: 1px solid #e9e6dd; }
.team-member:last-child { border-bottom: 0; }
.team-member .avatar { width: 27px; height: 27px; border-radius: 50%; background: var(--ink); color: var(--green); display: grid; place-items: center; font: 600 8px var(--display); }
.team-member div { min-width: 0; }
.team-member b { display: block; font: 600 9.5px var(--display); }
.team-member span { font: 6.5px var(--mono); color: var(--muted); }
.team-member .badge { margin-left: auto; }
.add-admin-form { padding: 0 17px 17px; display: flex; flex-direction: column; gap: 8px; }
.add-admin-form input { border: 1px solid var(--line); background: var(--white); padding: 8px 10px; font: 10.5px var(--display); outline: 0; }
.data-actions { padding: 15px 17px; display: flex; flex-direction: column; gap: 7px; }
.data-actions button { justify-content: space-between; }
.security-note { font: 7.5px/1.65 var(--mono); color: var(--muted); padding: 0 17px 17px; }
.security-note b { color: var(--ink); font-weight: 500; }

/* ---------- toast ---------- */
.admin-toast {
  position: fixed; z-index: 100; left: 50%; bottom: 20px; transform: translate(-50%, 18px);
  background: var(--ink); color: var(--paper); padding: 12px 18px; font: 8.5px var(--mono);
  letter-spacing: .02em; opacity: 0; visibility: hidden; transition: .25s; white-space: nowrap;
  max-width: calc(100% - 30px); overflow: hidden; text-overflow: ellipsis;
}
.admin-toast.show { opacity: 1; visibility: visible; transform: translate(-50%, 0); }

/* ---------- responsivo ---------- */
@media (max-width: 1150px) {
  .admin-kpis { grid-template-columns: 1fr 1fr; }
  .dash-grid { grid-template-columns: 1fr; }
  .collection-grid { grid-template-columns: 1fr 1fr; }
  .settings-grid { grid-template-columns: 1fr; }
}
@media (max-width: 850px) {
  .admin-login { grid-template-columns: 1fr; }
  .login-brand { min-height: 260px; padding: 27px 7vw 22px; }
  .login-brand-copy { padding: 34px 0 20px; }
  .login-brand h1 { font-size: 54px; margin: 17px 0 12px; }
  .login-brand p { font-size: 11px; max-width: 300px; }
  .login-brand-foot { display: none; }
  .login-panel { padding: 60px 7vw 45px; }
  .login-back { top: 23px; right: 7vw; }
  .login-form-wrap { max-width: 420px; }
  .admin-sidebar { transform: translateX(-102%); transition: transform .25s; width: 244px; box-shadow: 20px 0 50px #00000035; }
  .admin-sidebar.open { transform: none; }
  .admin-sidebar-scrim { display: block; position: fixed; inset: 0; background: #10110f75; z-index: 40; opacity: 0; visibility: hidden; transition: .25s; }
  .admin-sidebar-scrim.open { opacity: 1; visibility: visible; }
  .admin-shell { margin-left: 0; }
  .admin-topbar { height: 78px; padding: 0 17px; gap: 13px; }
  .topbar-title h1 { font-size: 19px; }
  .mobile-nav-toggle { display: block; }
  .admin-content { padding: 20px 16px 50px; }
  .admin-user div { display: none; }
  .panel-heading h2 { font-size: 28px; }
  .collection-grid { grid-template-columns: 1fr; }
}
@media (max-width: 560px) {
  .admin-kpis { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .form-grid .span-2 { grid-column: auto; }
  .form-image-row { grid-template-columns: 1fr 55px; }
  .form-image-row img { width: 55px; height: 64px; }
  .checkbox-grid { grid-template-columns: 1fr; }
  .order-info-grid { grid-template-columns: 1fr; }
  .settings-form { grid-template-columns: 1fr; }
  .settings-form .span-2 { grid-column: auto; }
  .panel-heading { align-items: flex-start; }
  .panel-actions { width: 100%; }
  .panel-actions .admin-button { flex: 1; }
  .admin-user { gap: 0; }
  .order-detail-actions { flex-direction: column; align-items: flex-start; }
}

/* RUA 98 — painel administrativo */
(async () => {
  await RUA98.ready();

  const $ = selector => document.querySelector(selector);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[char]));
  const money = value => `R$ ${Number(value || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const shortMoney = value => Number(value || 0) % 1 === 0
    ? `R$ ${Number(value).toLocaleString('pt-BR')}`
    : money(value);
  const dateBR = value => value
    ? new Date(value).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' }).replace('.', '').toUpperCase()
    : '—';
  const inputDate = value => value ? String(value).slice(0, 10) : '';
  const statusLabels = {
    pendente: 'AGUARDANDO PAGAMENTO',
    pago: 'PAGO',
    enviado: 'ENVIADO',
    entregue: 'ENTREGUE',
    cancelado: 'CANCELADO'
  };
  const orderStatuses = ['pendente', 'pago', 'enviado', 'entregue', 'cancelado'];
  const titles = {
    dashboard: 'VISÃO GERAL',
    products: 'PRODUTOS',
    drops: 'LANÇAMENTOS',
    collections: 'COLEÇÕES',
    orders: 'PEDIDOS',
    customers: 'CLIENTES',
    settings: 'CONFIGURAÇÕES'
  };
  const state = {
    panel: 'dashboard',
    productSearch: '',
    orderFilter: 'todos',
    orderSearch: '',
    customerSearch: ''
  };
  let me = null;
  let toastTimer;

  const loginScreen = $('#admin-login');
  const app = $('#admin-app');
  const content = $('#admin-content');
  const modalRoot = $('#admin-modal-root');
  const sidebar = $('#admin-sidebar');
  const sidebarScrim = $('#admin-sidebar-scrim');

  function toast(message) {
    const element = $('#admin-toast');
    element.textContent = message;
    element.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => element.classList.remove('show'), 2800);
  }

  function statusBadge(status) {
    return `<span class="badge ${esc(status)}">${statusLabels[status] || esc(String(status).toUpperCase())}</span>`;
  }

  function statusOptions(selected) {
    return orderStatuses.map(status => `<option value="${status}" ${status === selected ? 'selected' : ''}>${statusLabels[status]}</option>`).join('');
  }

  function sidebarCounts() {
    const orders = RUA98.orders();
    $('#nav-order-count').textContent = orders.filter(order => order.status === 'pendente').length;
  }

  function renderUser() {
    me = RUA98.currentUser();
    if (!me) return;
    const initials = me.name.split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]).join('').toUpperCase();
    $('#admin-user-avatar').textContent = initials || 'A';
    $('#admin-user-name').textContent = me.name;
  }

  function showLogin() {
    me = null;
    loginScreen.hidden = false;
    app.hidden = true;
    $('#admin-login-form').reset();
    $('#login-error').hidden = true;
    updateLoginNote();
    closeSidebar();
  }

  function updateLoginNote() {
    const note = $('#login-session-note');
    const user = RUA98.currentUser();
    if (user && user.role !== 'admin') {
      note.innerHTML = `Você está conectado como <b>${esc(user.name)}</b> (cliente). Entre com uma conta administrativa para continuar. <button type="button" id="login-session-logout">SAIR DESTA CONTA</button>`;
      note.hidden = false;
      $('#login-session-logout').addEventListener('click', () => {
        RUA98.logout();
        updateLoginNote();
        toast('SESSÃO DE CLIENTE ENCERRADA.');
      });
    } else {
      note.hidden = true;
      note.innerHTML = '';
    }
  }

  function enterApp() {
    const user = RUA98.currentUser();
    if (!user || user.role !== 'admin') {
      showLogin();
      return;
    }
    me = user;
    loginScreen.hidden = true;
    app.hidden = false;
    renderUser();
    sidebarCounts();
    render();
  }

  function openSidebar() { sidebar.classList.add('open'); sidebarScrim.classList.add('open'); }
  function closeSidebar() { sidebar.classList.remove('open'); sidebarScrim.classList.remove('open'); }

  function render() {
    if (!me) return;
    renderUser();
    sidebarCounts();
    const activePanel = state.panel;
    document.querySelectorAll('.admin-nav [data-panel]').forEach(button => {
      button.classList.toggle('active', button.dataset.panel === activePanel);
    });
    $('#admin-page-title').textContent = titles[activePanel];
    document.title = `${titles[activePanel]} — Painel RUA 98`;
    if (activePanel === 'dashboard') renderDashboard();
    if (activePanel === 'products') renderProducts();
    if (activePanel === 'drops') renderDrops();
    if (activePanel === 'collections') renderCollections();
    if (activePanel === 'orders') renderOrders();
    if (activePanel === 'customers') renderCustomers();
    if (activePanel === 'settings') renderSettings();
    closeSidebar();
  }

  /* ---------------- dashboard ---------------- */
