  function deleteProduct(id) {
    const product = RUA98.product(id);
    if (!product) return;
    confirmAction({
      title: 'EXCLUIR PEÇA',
      text: `A peça <b>${esc(product.name)}</b> será removida da loja, das sacolas e dos favoritos. Essa ação não pode ser desfeita.`,
      label: 'EXCLUIR PEÇA',
      onConfirm: () => {
        RUA98.deleteProduct(id);
        render();
        toast('PEÇA EXCLUÍDA.');
      }
    });
  }

  /* ---------------- lançamentos ---------------- */
